def _grep_config(repo_root: Path, stem: str) -> str:
    """Search ``repo_root/config/**`` for ``stem`` used as a MODULE reference.

    A reference counts only when ``stem`` looks like a module path / ``-m``
    target -- a ``stem.py`` file path, a dotted-path segment (``pkg.stem`` or
    ``stem.sub``), or a bare ``-m <stem>`` target -- NOT when it is merely a
    bare identifier or JSON object key (which previously produced false
    CONFIG_WIRED verdicts that masked real orphans).

    Returns the POSIX rel-path of the first config file that references the
    stem (dynamic/config-string wiring), or "" if none does.
    """
    config_dir = repo_root / 'config'
    if not config_dir.is_dir():
        return ''
    s = re.escape(stem)
    pattern = re.compile('(?<![\\w.])' + s + '\\.py\\b' + '|(?<=\\.)' + s + '\\b' + '|(?<![\\w.])' + s + '(?=\\.\\w)' + '|-m\\s+' + s + '\\b')
    for path in sorted(config_dir.rglob('*')):
        if not path.is_file():
            continue
        try:
            text = path.read_text(encoding='utf-8', errors='ignore')
        except OSError:
            continue
        if pattern.search(text):
            try:
                return path.relative_to(repo_root).as_posix()
            except ValueError:
                return path.as_posix()
    return ''
```

The compiled pattern has four alternatives: (1) `(?<![\w.])stem\.py\b` -- a stem.py path token not preceded by a word char or dot; (2) `(?<=\.)stem\b` -- stem as a dotted-path tail (preceded by a dot); (3) `(?<![\w.])stem(?=\.\w)` -- stem as a dotted-path head (followed by .identifier); (4) `-m\s+stem\b` -- a bare `-m <module>` target. `stem` is the re.escape'd value `s`. Do NOT cite repo line numbers. Do NOT touch any other symbol. The committed oracle tests/harness/test_grep_config_module_ref.py is authoritative -- your code MUST make it pass and MUST keep tests/harness/test_sweep_classifier.py, test_wire_up.py, and test_wire_tracer_accuracy.py passing.
